#!/bin/sh
# Name: SSH·修复
# Author: Stone
# Icon: data:image/png;base64,
# v2：修复 dropbear strictmodes 权限问题 + 双写密钥
# 公钥由使用者自己提供：把 ~/.ssh/id_*.pub 的内容放到这个文件
PUBKEY=/mnt/us/kindle-dash/authorized_keys.pub
LOG=/mnt/us/ssh_fix.log
{
echo "=== $(date) v2 ==="
RH=$(awk -F: '/^root:/{print $6}' /etc/passwd)
echo "root home = $RH"
for HOME_DIR in /root "$RH"; do
    mkdir -p "$HOME_DIR/.ssh"
    if [ -f "$PUBKEY" ]; then
        cat "$PUBKEY" > "$HOME_DIR/.ssh/authorized_keys"
    else
        echo "缺少公钥文件 $PUBKEY —— 请先把自己的公钥放到该路径"
    fi
    # strictmodes：家目录不能 group/other 可写
    chmod 755 "$HOME_DIR"
    chmod 700 "$HOME_DIR/.ssh"
    chmod 600 "$HOME_DIR/.ssh/authorized_keys"
    chown root:root "$HOME_DIR" "$HOME_DIR/.ssh" "$HOME_DIR/.ssh/authorized_keys" 2>/dev/null
    echo "$HOME_DIR 权限: $(ls -ld $HOME_DIR | awk '{print $1}') key md5: $(md5sum $HOME_DIR/.ssh/authorized_keys | cut -d' ' -f1)"
done
echo "--- 重启 SSH ---"
pkill dropbear 2>/dev/null
rm -f /mnt/us/usbnet/run/sshd.pid
sleep 1
/mnt/us/usbnet/bin/usbnetwork
echo "done"
} >> $LOG 2>&1
